from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); g=[row[:] for row in grid]
    # The background is the most frequent color; identify its enclosed regions.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    # Label connected non-background objects and record their bounds.
    labels=[[-1]*w for _ in range(h)]; bounds=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or labels[r][c]>=0: continue
            k=len(bounds); q=[(r,c)]; labels[r][c]=k; cells=[]
            for y,x in q:
                cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg and labels[yy][xx]<0:
                        labels[yy][xx]=k; q.append((yy,xx))
            bounds.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or seen[r][c]: continue
            q=[(r,c)]; seen[r][c]=True; cells=[]; edge=False; adj=set()
            for y,x in q:
                cells.append((y,x))
                if y==0 or x==0 or y==h-1 or x==w-1: edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if not (0<=yy<h and 0<=xx<w):
                        edge=True
                    elif grid[yy][xx]==bg and not seen[yy][xx]:
                        seen[yy][xx]=True; q.append((yy,xx))
                    elif grid[yy][xx]!=bg and labels[yy][xx]>=0:
                        adj.add(labels[yy][xx])
            if not edge and adj:
                # A hole is filled according to the parity of its enclosing frame size.
                rs=[bounds[k][1]-bounds[k][0]+1 for k in adj]
                cs=[bounds[k][3]-bounds[k][2]+1 for k in adj]
                color=7 if all(v%2 for v in rs+cs) else 2
                for y,x in cells: g[y][x]=color
    return g

